from dateutil.relativedelta import relativedelta

random.seed(0)
bad = []
for _ in range(200000):
    def rdt():
        return datetime.datetime(random.randint(1,9999), random.randint(1,12), random.randint(1,28),
                                 random.randint(0,23), random.randint(0,59), random.randint(0,59), random.randint(0,999999))
    d1, d2 = rdt(), rdt()
    rd = relativedelta(d1, d2)
    got = d2 + rd
    if got != d1:
        bad.append((d1, d2, rd, got))
        if len(bad) >= 5:
            break
print("property d2 + relativedelta(d1,d2) == d1 : failures:", len(bad))
for b in bad[:5]:
    print(b)
